with filtered as (select id, channel, promo_code, starts_on, ends_on, discount_pct, datediff(current_date(), starts_on) as days_since_starts_on, coalesce(channel, 'OTHER') as channel_filled from promotions where starts_on > date '2023-04-17') select id, channel, promo_code, starts_on, channel_filled, first_value(days_since_starts_on) ignore nulls over (partition by date_trunc('YEAR', ends_on), channel order by ends_on, id rows between unbounded preceding and current row) as first_known_days_since_starts_on, ntile(5) over w_grp as days_since_starts_on_bucket from filtered where discount_pct > 0.15 window w_grp as (order by days_since_starts_on, id);
